/// Reports whether [tagNumber] of [message] is a proto3 `optional` field.
///
/// Such a field has explicit presence: proto3 JSON omits it when unset
/// even where implicit-presence defaults are emitted. The generated
/// BuilderInfo does not record this, so the schema is consulted here.
bool payloadFieldIsProto3Optional(GeneratedMessage message, int tagNumber) {
  final fields = _explicitPresenceFields[message.info_.qualifiedMessageName];
  return fields != null && fields.contains(tagNumber);
}

GeneratedMessage? decodeEmptyRpcResponsePayload(String methodName) {
  final type = rpcMethodByName(methodName).responseType;
  final message = newPayloadMessage(type);
  return message.info_.fieldInfo.isEmpty ? message : null;
}

void _expectPayloadType(String expected, GeneratedMessage message) {
  final expectedType = _messageTypes[expected];
  if (expectedType == null) {
    throw ArgumentError.value(expected, 'expected', 'unknown RPC payload type');
  }
  final actualType = message.runtimeType;
  if (actualType != expectedType) {
    throw ArgumentError(
      'RPC payload type mismatch: got $actualType, want $expected',
    );
  }
}
